const math = { cos: Math.cos, sin: Math.sin, radians: d => d * Math.PI / 180 };
const cx=60, cy=60, r_o=32, r_i=27, n=24;
const pt = \(deg, r\) => {
  const a = math.radians\(deg\);
  return \(cx + r*math.cos\(a\)\).toFixed\(1\) + ',' + \(cy + r*math.sin\(a\)\).toFixed\(1\);
};
const parts = [];
for\(let i=0;i<n;i++\){
  const base=i*15;
  parts.push\(\(i===0?'M ':'L '\) + pt\(base,r_i\)\);
  parts.push\('L '+pt\(base+3,r_o\)+' L '+pt\(base+12,r_o\)\);
}
parts.push\('Z'\);
const r_h=23;
parts.push\('M '+\(cx+r_h\).toFixed\(1\)+','+cy.toFixed\(1\)\);
parts.push\('A '+r_h+' '+r_h+' 0 1 0 '+\(cx-r_h\).toFixed\(1\)+','+cy.toFixed\(1\)\);
parts.push\('A '+r_h+' '+r_h+' 0 1 0 '+\(cx+r_h\).toFixed\(1\)+','+cy.toFixed\(1\)\);
parts.push\('Z'\);
console.log\(parts.join\(' '\)\);
")

