const sharp = require\('sharp'\);
const REF = 'D:/negocios/sirgrimorum/docs/art-direction/references';
const PUB = 'D:/negocios/sirgrimorum/apps/web-sirgrimorum/public';

// For the favicon we want:
// - Strongly boosted shadows and highlights \(normalize + clahe + linear contrast\)
// - Sharper edges so border and dragon read at 64px
async function run\(\) {
  await sharp\(REF+'/dragon-seal-3-clean.png'\)
    .normalize\(\)                          // stretch histogram to full range
    .clahe\({ width: 8, height: 8, maxSlope: 4 }\)  // local contrast boost
    .linear\(1.6, -55\)                     // lift shadows/highlights apart
    .sharpen\({ sigma: 1.2, m1: 1.5, m2: 12 }\)  // crisp edges at small size
    .resize\(64, 64, { fit:'contain', background:{r:0,g:0,b:0,alpha:0} }\)
    .png\(\)
    .toFile\(PUB+'/favicon.png'\);
  console.log\('favicon done'\);
}
run\(\).catch\(console.error\);
")
